changeSet.sql:
UPDATE main_profile_outbox o SET user_id=u.id,email=u.email,username=u.username,name=u.name,avatar_url=u.avatar_url,
 role=u.role,profile_version=u.profile_version,status='PENDING',attempts=0,next_attempt_at=CURRENT_TIMESTAMP,last_error=NULL
FROM users u WHERE u.legacy_id=o.legacy_user_id;
INSERT INTO main_profile_outbox(id,user_id,legacy_user_id,email,username,name,avatar_url,role,profile_version,status,attempts,next_attempt_at,created_at,updated_at)
SELECT gen_random_uuid(),u.id,u.legacy_id,u.email,u.username,u.name,u.avatar_url,u.role,u.profile_version,'PENDING',0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP
FROM users u WHERE NOT EXISTS(SELECT 1 FROM main_profile_outbox o WHERE o.user_id=u.id);
